3	import Anthropic from "@anthropic-ai/sdk";
4	import { taggingJsonSchema } from "./tagging-schema";
5	import { parseTagText } from "./parse-tags";
6	
7	const client = new Anthropic(); // reads ANTHROPIC_API_KEY (server-only)
8	
9	const PROMPT = `You are a fashion catalog tagger. Analyze the single clothing item in the \
10	image and return ONLY the structured tags. category is the garment family; subcategory is \
11	specific (e.g. Oxford shirt, Chinos, Penny loafers); colors lists the 1-3 dominant colours; \
12	formality is 1 (very casual) to 5 (formal); seasons are the seasons it suits.`;
13	
14	export async function tagItem(
15	  cutoutBase64: string,
16	  mediaType: "image/png" | "image/jpeg",
17	) {
18	  const res = await client.messages.create({
19	    model: "claude-haiku-4-5",
20	    max_tokens: 512,
21	    output_config: { format: { type: "json_schema", schema: taggingJsonSchema } },
22	    messages: [
23	      {
24	        role: "user",
25	        content: [
26	          { type: "image", source: { type: "base64", media_type: mediaType, data: cutoutBase64 } },
27	          { type: "text", text: PROMPT },
28	        ],
29	      },
30	    ],
31	  });
32	  const text = res.content.find((b) => b.type === "text")?.text ?? "{}";
33	  return parseTagText(text); // validated Tags (a draft shown on the confirm screen)
34	}
