5	/** Browser-only: compress, then cut out the background on-device. */
6	export async function processImage(
7	  file: File,
8	): Promise<{ original: Blob; cutout: Blob }> {
9	  const original = await imageCompression(file, compressionOptions());
10	  const cutout = await removeBackground(original); // @imgly WASM, on-device
11	  return { original, cutout };
12	}
