14	export function blobToBase64(blob: Blob): Promise<string> {
15	  return new Promise((resolve, reject) => {
16	    const reader = new FileReader();
17	    reader.onload = () => resolve(String(reader.result).split(",")[1] ?? "");
18	    reader.onerror = reject;
19	    reader.readAsDataURL(blob);
20	  });
21	}
