3	import { revalidatePath } from "next/cache";
4	import { createClient } from "@/lib/supabase/server";
5	import { tagItem } from "@/lib/ai/tag-item";
6	import { TagSchema } from "@/lib/ai/tagging-schema";
7	import { tagsToItemRow } from "@/lib/ai/parse-tags";
8	
9	// Upload both blobs to Storage, then return a DRAFT tag set for the confirm
10	// screen. No DB insert yet — the user confirms first.
11	export async function uploadAndTag(form: {
12	  originalB64: string;
13	  cutoutB64: string;
14	  mediaType: "image/png" | "image/jpeg";
15	}) {
16	  const supabase = await createClient();
17	  const {
18	    data: { user },
19	  } = await supabase.auth.getUser();
20	  if (!user) throw new Error("Not authenticated");
21	
22	  const itemId = crypto.randomUUID();
23	  const base = `${user.id}/${itemId}`;
24	  const orig = Buffer.from(form.originalB64, "base64");
25	  const cut = Buffer.from(form.cutoutB64, "base64");
26	
27	  await supabase.storage.from("wardrobe").upload(`${base}/original.jpg`, orig, {
28	    contentType: "image/jpeg",
29	  });
30	  await supabase.storage.from("wardrobe").upload(`${base}/cutout.png`, cut, {
31	    contentType: "image/png",
32	  });
33	
34	  const tags = await tagItem(form.cutoutB64, form.mediaType);
35	  return {
36	    itemId,
37	    imagePath: `${base}/original.jpg`,
38	    cutoutPath: `${base}/cutout.png`,
39	    tags,
40	  };
41	}
