43	// Re-validate the (possibly user-edited) tags and insert the item.
44	export async function confirmItem(input: {
45	  imagePath: string;
46	  cutoutPath: string;
47	  name?: string | null;
48	  brand?: string | null;
49	  tags: unknown;
50	}) {
51	  const supabase = await createClient();
52	  const {
53	    data: { user },
54	  } = await supabase.auth.getUser();
55	  if (!user) throw new Error("Not authenticated");
56	
57	  const tags = TagSchema.parse(input.tags);
58	  const row = {
59	    ...tagsToItemRow({
60	      userId: user.id,
61	      imageUrl: input.imagePath,
62	      cutoutUrl: input.cutoutPath,
63	      tags,
64	    }),
65	    name: input.name ?? tags.subcategory,
66	    brand: input.brand ?? null,
67	  };
68	  const { error } = await supabase.from("items").insert(row);
69	  if (error) throw error;
70	  revalidatePath("/closet");
71	}
