1	import { createServerClient } from "@supabase/ssr";
2	import { NextResponse, type NextRequest } from "next/server";
3	
4	export async function updateSession(request: NextRequest) {
5	  let response = NextResponse.next({ request });
6	
7	  const supabase = createServerClient(
8	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
9	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
10	    {
11	      cookies: {
12	        getAll: () => request.cookies.getAll(),
13	        setAll: (toSet) => {
14	          toSet.forEach(({ name, value }) => request.cookies.set(name, value));
15	          response = NextResponse.next({ request });
16	          toSet.forEach(({ name, value, options }) =>
17	            response.cookies.set(name, value, options),
18	          );
19	        },
20	      },
21	    },
22	  );
23	
24	  // Refreshes the auth token and rewrites the cookies. Do not run other logic
25	  // between createServerClient and getUser() — it can cause random logouts.
26	  await supabase.auth.getUser();
27	
28	  return response;
29	}
