1	import { createClient } from "@/lib/supabase/server";
2	
3	export async function signItemImages(paths: string[], expiresIn = 3600) {
4	  const map = new Map<string, string>();
5	  if (paths.length === 0) return map;
6	  const supabase = await createClient();
7	  const { data } = await supabase.storage
8	    .from("wardrobe")
9	    .createSignedUrls(paths, expiresIn);
10	  data?.forEach((d) => {
11	    if (d.path && d.signedUrl) map.set(d.path, d.signedUrl);
12	  });
13	  return map;
14	}
