1	import { createServerClient } from "@supabase/ssr";
2	import { cookies } from "next/headers";
3	
4	export async function createClient() {
5	  const cookieStore = await cookies();
6	  return createServerClient(
7	    process.env.NEXT_PUBLIC_SUPABASE_URL!,
8	    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
9	    {
10	      cookies: {
11	        getAll: () => cookieStore.getAll(),
12	        setAll: (toSet) => {
13	          try {
14	            toSet.forEach(({ name, value, options }) =>
15	              cookieStore.set(name, value, options),
16	            );
17	          } catch {
18	            // Called from a Server Component — the middleware refreshes the session.
19	          }
20	        },
21	      },
22	    },
23	  );
24	}
